from math import sqrt

def transform(grid):
    out = [row[:] for row in grid]
    n = len(grid)
    t = round(sqrt(n + 1))
    stride = t + 1
    k = (n + 1) // stride
    starts = [i * stride for i in range(k)]

    def get_tile(i, j):
        return [grid[starts[i] + r][starts[j] + c] for r in range(t) for c in range(t)]

    def tile_kind(tile):
        if 3 in tile or all(x == 0 for x in tile):
            return None
        return tuple(2 if x == 8 else x for x in tile)

    tiles = [[get_tile(i, j) for j in range(k)] for i in range(k)]
    known = [(i, j, tile_kind(tiles[i][j])) for i in range(k) for j in range(k)
             if tile_kind(tiles[i][j]) is not None]

    for i in range(k):
        for j in range(k):
            tile = tiles[i][j]
            if 3 in tile:
                # Infer the missing repeated tile from the closest visible copy.
                dmin = min(abs(i - a) + abs(j - b) for a, b, _ in known)
                candidates = [p for a, b, p in known if abs(i-a) + abs(j-b) == dmin]
                pattern = Counter(candidates).most_common(1)[0][0]
                # The repeated pattern is present here only when its (i,j) marker cell is 2.
                if pattern[i][j] == 2:
                    for r in range(t):
                        for c in range(t):
                            out[starts[i] + r][starts[j] + c] = pattern[r][c]
                else:
                    for r in range(t):
                        for c in range(t):
                            out[starts[i] + r][starts[j] + c] = 0
            else:
                # Clear separators/empty tiles and mark the tile's own coordinate in its copy.
                if all(x == 0 for x in tile):
                    continue
                if i < t and j < t and tile[i * t + j] == 2:
                    out[starts[i] + i][starts[j] + j] = 8
            # A 3-marked missing band is replaced by the inferred tile or by zeroes.
    # The 3s only occur inside the missing tiles; ensure no marker remains.
    for r in range(n):
        for c in range(n):
            if out[r][c] == 3:
                out[r][c] = 0
    return out
