def transform(grid):
    n = len(grid)
    # Tile separators are the all-zero rows/columns between repeated square tiles.
    sep_rows = [r for r, row in enumerate(grid) if all(v == 0 for v in row)]
    sep_cols = [c for c in range(n) if all(grid[r][c] == 0 for r in range(n))]
    steps = [b - a for a, b in zip(sep_rows, sep_rows[1:])]
    if not steps:
        steps = [b - a for a, b in zip(sep_cols, sep_cols[1:])]
    step = Counter(steps).most_common(1)[0][0]
    tile_size = step - 1
    starts = list(range(0, n, step))
    k = len(starts)

    def tile_at(i, j):
        return [[grid[starts[i] + r][starts[j] + c] for c in range(tile_size)]
                for r in range(tile_size)]

    tiles = [[tile_at(i, j) for j in range(k)] for i in range(k)]
    known = [t for row in tiles for t in row if any(v == 2 for rr in t for v in rr)]
    patterns = [tuple(tuple(2 if v == 8 else v for v in rr) for rr in t) for t in known]
    pattern = Counter(patterns).most_common(1)[0][0]

    out = [row[:] for row in grid]
    for i in range(k):
        for j in range(k):
            tile = tiles[i][j]
            sr, sc = starts[i], starts[j]
            if any(v == 3 for rr in tile for v in rr):
                # The tile is omitted unless its pattern cell at (tile-row,tile-column) is occupied.
                if i < tile_size and j < tile_size and pattern[i][j] == 2:
                    for r in range(tile_size):
