    assert k * (k + 1) - 1 == n
    stride = k + 1
    starts = [i * stride for i in range(k)]

    def tile(i, j):
        return tuple(tuple(grid[starts[i] + r][starts[j] + c] for c in range(k))
                     for r in range(k))

    tiles = [[tile(i, j) for j in range(k)] for i in range(k)]
    # Recover the common motif from the intact tiles; ignore empty and 3-marked placeholders.
    motif_candidates = [t for row in tiles for t in row
