        for j in range(k):
            t = tiles[i][j]
            marked = any(v == 3 for line in t for v in line)
            if marked:
                # A missing tile is present exactly when the motif has a 2 at its tile coordinate.
                for r in range(k):
                    for c in range(k):
                        out[starts[i] + r][starts[j] + c] = motif[r][c] if motif[i][j] == 2 else 0
            elif any(v == 2 for line in t for v in line):
